679	// ManifestConflictError reports that a manifest record disagrees with the
680	// record already registered, or introduced earlier in the same manifest,
681	// under the same batch id. Position is the record's 1-based position in the
682	// manifest and Fields lists every differing member among "product",
683	// "quantity" and "unit" in that order.
684	type ManifestConflictError struct {
685		Position int
686		Batch    string
687		Fields   []string
688		Source   string // "registry" or "manifest"
689		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
690	}
691	
692	func (e *ManifestConflictError) Error() string {
693		if e.Source == "manifest" {
694			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
695				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
696		}
697		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
698			e.Position, e.Batch, strings.Join(e.Fields, ", "))
699	}
